select 'Gastos restantes' as concepto,count(*) as total from public.expenses union all select 'Repartos restantes',count(*) from public.expense_fund_allocations union all select 'Historial de gastos restante',count(*) from public.audit_logs where entity in ('expenses','expense_fund_allocations','template_batch_items') union all select 'Respuestas de gastos restantes',count(*) from public.idempotency_requests where operation='create_expense' or response ? 'expense_id';